create temp table _kbpar(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kbpar(node_id, blocks, search_text) values
(40, $kbpar$[{"t":"list","id":"a1-1-1-1-b1","imp":"normal","items":["1、1946 年美国宾州大学研制成功第一台数字电子计算机——ENIAC（十进制、未采用存储程序）。\n世界上首先实现存储程序的电子数字计算机是“EDVAC”。EDVAC（离散变量自动电子计算机）采用二进制，是一台冯·诺依曼结构的计算机；\n第一台按存储程序设计的计算机是 EDVAC，第一台实际运行存储程序控制功能的计算机是 EDSAC，ENIAC 只是第一台电子数字计算机。","2、冯·诺依曼提出“存储程序控制”原理：程序和数据必须从外存调入内存，再交给 CPU。冯·诺依曼的计算机特点：","（1）计算机由五大部件组成：存储器，运算器，控制器，输入设备，输出设备。","（2）指令和数据以同等地位存于存储器，可按地址顺序访问。","（3）指令和数据用二进制表示。","（4）指令由操作码和地址码组成。","（5）存储程序，程序在计算机中顺序存放。","（6）机器以运算器为中心，输入/输出设备和存储器的数据传送通过运算器。","现在的计算机基本以存储器为中心，下图为以存储器为中心的计算机结构框图。"],"title":"","ordered":false},{"t":"img","id":"a1-1-1-1-b2","imp":"normal","src":"/kb-assets/theory/p6_r0_6c5dade9e65d45c2.png","w":1191,"h":549,"alt":"以存储器为中心的计算机结构框图","caption":"图1-2 以存储器为中心的计算机结构框图（输入/输出设备直接与存储器交换数据）","title":""},{"t":"list","id":"a1-1-1-1-b3","imp":"normal","items":["3、计算机发展（使用的元器件）的四个阶段：","第一代电子管计算机时代（1946-1957）：真空电子管，使用机器语言或汇编语言。","第二代晶体管计算机时代（1958-1964）：晶体管，出现高级程序设计语言。","第三代中小规模集成电路计算机时代（1965-1970）：中小规模集成电路，操作系统和数据库系统出现。","第四代大规模集成电路计算机时代（1971-至今）：大规模和超大规模集成电路，软件开发工具和平台、分布式计算、网络软件等出现；微型计算机（PC）出现。","4、计算机的分类：","（1）按照计算机的工作原理（处理数据方式）：数字式电子计算机、模拟式电子计算机、数字模拟混合式电子计算机。","（2）按照计算机的用途：通用计算机、专用计算机。","（3）按照计算机的性能（规模）和价格（红色主要用于服务器）分：巨型机（“神威”、“天河”系列等）、小巨型机、大型机、小型机、工作站、个人计算机（PC）、嵌入式计算机（核心是 SoC 片上系统）。","（4）按主机外型：台式、便携式。","（5）按中央处理器的字长分：8 位、16 位、32 位、64 位等。","（6）计算机特性以及未来发展（微型化和智能化）：","目前的计算机使用的都是半导体集成电路，现在不断努力研究其他材料。","量子计算机：建立在量子力学基础上，可以同时使用多个不同的量子态来处理和存储信息。","光学计算机：以光子代替电子，光互连代替导线互连，光硬件代替计算机中的电子硬件，光运算代替电运算。","生物计算机：蛋白质分子与周围物理化学介质的相互作用过程。计算机的转换开关由酶来充当，而程序则在酶合成系统本身和蛋白质的结构中极其明显地表示出来。预计 10～20 年后，DNA 计算机将进入实用阶段。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-1-b4","imp":"normal","items":["5、计算机的特点：运算速度快、运算精度高、存储容量大、计算可靠性高（7×24 小时服务）、能进行逻辑判断、通用性好、支持人机交互等。","6、计算机的应用领域：科学计算（最早应用场景）、信息处理（办公自动化 OA）、计算机辅助技术（辅助设计 CAD；辅助制造 CAM、辅助教学 CAI、辅助测试 CAT）、过程控制、人工智能、网络应用、多媒体等。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-1-b7","imp":"normal","items":["7、一个完整计算机系统是由配套的硬件设备和软件系统组成。硬件主要由五大部件构成：运算器、控制器、存储器、输入设备和输出设备，它们通过总线相互连接。如下图所示："],"title":"","ordered":false},{"t":"img","id":"a1-1-1-1-b8","imp":"normal","src":"/kb-assets/theory/p7_r0_aff251d8271afc55.png","w":834,"h":472,"alt":"计算机系统硬件与软件层次构成图","caption":"计算机系统组成结构：硬件系统（主机与外设）及软件系统（系统/应用软件）","title":""},{"t":"list","id":"a1-1-1-1-b9","imp":"normal","items":["主机：CPU、内存储器、总线等构成了计算机的“主机”。","外设（外部设备）：外部存储器（外存）和 I/O 设备构成。","CPU（中央处理器）：主要由运算器和控制器组成，也称微处理器。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-1-b10","imp":"normal","items":["8、按性能与用途划分的各类计算机：巨型计算机（超级计算机）采用并行处理，用于军事科研、气象预报、石油勘探、生物信息处理、飞机设计等领域，我国目前最快的是“神威·太湖之光”。大型计算机为企业、政府的海量数据提供集中的存储、管理和处理，承担主服务器（企业级服务器）的功能，可一二十年不间断运行。服务器是网络中专门为其他计算机提供资源和服务的计算机，需 7×24 小时运行，分为工作组级（家用）、部门级、企业级服务器，浪潮集团是我国最大的服务器制造商；服务器有三种应用方式：作为服务器、作为个人计算机、嵌入式应用。","9、计算机硬件组成：主机与外设：硬件是计算机系统中所有实际物理装置的总称，如 CPU 芯片、存储器芯片、鼠标、键盘、硬盘；硬件是软件的载体，软硬件缺一不可。CPU 和主存储器构成主机的主体部分，I/O 设备和辅助存储器构成外围设备（外设）。主存储器（内存、主存）存取速度快、容量小、成本高，断电后信息几乎消失（BIOS 中的只读 ROM 除外），属易失性存储器；它存放已经启动的应用程序和需立即处理的数据，CPU 处理的指令和数据直接从内存取得；主存与 CPU 高速连接，按字节编址（每个字节都有地址），是计算机的工作存储器。","10、计算机的诞生与发展：计算机速度不断提高、功能增加、体积缩小、成本降低、应用扩大，发展之快不断改写预测：早期 8～10 年运算速度提高十倍，而成本和体积降为原来的 1/10；20 世纪 80 年代开始，几乎每三年性能提高近四倍，成本下降一半。推动力是微电子技术的进展和计算机应用的需求。","11、操作系统的四大功能：操作系统的功能主要有四个：","处理器管理（宏观上同时执行、微观上单一执行，采用时间片轮转的处理策略）","存储管理（采用“虚拟存储技术”，虚拟存储器由物理内存和硬盘上的页面文件组成，使用 LRU 算法）","文件管理（多级层次式树状结构）","设备管理（通过“我的电脑”快捷菜单“属性”中的“设备管理器”进行）。","12、多任务处理的机制与前后台任务：多任务处理指多个任务在计算机中同时运行，每个任务都可以使用包括 CPU 在内的几乎全部软硬件资源。任务是指装入内存并启动执行的一个程序。为支持多任务处理，操作系统中的处理器调度程序负责把 CPU 时间分配给各个任务，使多个任务“同时”执行。调度程序采用按时间片轮转的方法，每个任务轮流得到一个时间片的 CPU 时间，时间片结束后再把 CPU 交给下一个任务，因此一个 CPU 就可以“同时”执行多个任务。","13、实用程序包括哪些：实用程序包括磁盘扫描程序、磁盘清理程序、磁盘碎片整理程序、备份程序、杀毒软件、基本输入输出系统（BIOS）、防火墙等。","14、1946 年美国宾夕法尼亚大学研制成功第 1 台电子数字计算机 ENIAC（十进制、未采用存储程序）；第一台按“存储程序控制”原理设计并采用二进制的计算机是 EDVAC（冯·诺依曼架构），第一台实际运行存储程序控制功能的计算机是 EDSAC。","15、计算机发展的四个阶段：","第四代大规模集成电路计算机时代（1971–至今）：大规模和超大规模集成电路，网络技术、多媒体技术等出现。","16、计算机系统是由硬件系统和软件系统组成。","硬件系统主要由五大部件构成：运算器、控制器、存储器、输入设备和输出设备，它们通过总线相互连接。","五大硬件部件以存储器为中心的连接结构与控制器工作流程如下图所示："],"title":"","ordered":false},{"t":"callout","id":"a1-1-1-1-b5","imp":"core","kind":"tip","text":"专转本常考主线：==计算机四代划分以元器件为标志==（电子管→晶体管→中小规模IC→大规模/超大规模IC）；==冯·诺依曼“存储程序控制”==核心思想在于程序与数据预先存入内存储器，由 CPU 自动连续取指并执行；计算机按性能划分为==巨型机（超级计算机，我国神威系列）、大型机、小型机、微型机（PC）、嵌入式系统==。","title":"考向复习提示：计算机分类与存储程序原理"},{"t":"callout","id":"a1-1-1-1-b6","imp":"core","kind":"trap","text":"专转本常考单选：冯·诺依曼型计算机由五大基本逻辑部件组成：==运算器、控制器、存储器、输入设备、输出设备==；指令和数据均以二进制形式存放在同一个存储器中，由 CPU 顺序执行；常考陷阱选项故意将“存储器”偷换为“外存储器”或漏掉“控制器”，务必精准辨析。","title":"高频易错陷阱：冯·诺依曼架构五大逻辑部件"},{"t":"callout","id":"a1-1-1-1-p2-sync-tip","imp":"core","kind":"tip","text":"应试提示：教材与历年真题常以 ==神威·太湖之光== 作为我国超级计算机经典代表，作答传统考题时仍可沿用；以下为近年真实算力演进补充：\n• ^^超智融合演进^^：2023 年底发布的 ==天河星逸== 系统部署于国家超算广州中心，显著强化通用计算与人工智能大模型融合算力；\n• ==2026 年 6 月 TOP500 榜首回归==：部署于国家超级计算深圳中心的我国自研超算 ==灵晟（LineShine）== 以 ==2.198 Exaflop/s== 性能登顶全球第一，采用全自主 `LingKun` 平台（`Armv9` 架构 304 核 `LX2` 处理器）与国产 `Kylin OS`。","title":"考向复习提示：2025–2026 前沿同步：国产超算最新突破"}]$kbpar$::jsonb, $kbpars$1、1946 年美国宾州大学研制成功第一台数字电子计算机——ENIAC（十进制、未采用存储程序）。 世界上首先实现存储程序的电子数字计算机是“EDVAC”。EDVAC（离散变量自动电子计算机）采用二进制，是一台冯·诺依曼结构的计算机； 第一台按存储程序设计的计算机是 EDVAC，第一台实际运行存储程序控制功能的计算机是 EDSAC，ENIAC 只是第一台电子数字计算机。 2、冯·诺依曼提出“存储程序控制”原理：程序和数据必须从外存调入内存，再交给 CPU。冯·诺依曼的计算机特点： （1）计算机由五大部件组成：存储器，运算器，控制器，输入设备，输出设备。 （2）指令和数据以同等地位存于存储器，可按地址顺序访问。 （3）指令和数据用二进制表示。 （4）指令由操作码和地址码组成。 （5）存储程序，程序在计算机中顺序存放。 （6）机器以运算器为中心，输入/输出设备和存储器的数据传送通过运算器。 现在的计算机基本以存储器为中心，下图为以存储器为中心的计算机结构框图。 3、计算机发展（使用的元器件）的四个阶段： 第一代电子管计算机时代（1946-1957）：真空电子管，使用机器语言或汇编语言。 第二代晶体管计算机时代（1958-1964）：晶体管，出现高级程序设计语言。 第三代中小规模集成电路计算机时代（1965-1970）：中小规模集成电路，操作系统和数据库系统出现。 第四代大规模集成电路计算机时代（1971-至今）：大规模和超大规模集成电路，软件开发工具和平台、分布式计算、网络软件等出现；微型计算机（PC）出现。 4、计算机的分类： （1）按照计算机的工作原理（处理数据方式）：数字式电子计算机、模拟式电子计算机、数字模拟混合式电子计算机。 （2）按照计算机的用途：通用计算机、专用计算机。 （3）按照计算机的性能（规模）和价格（红色主要用于服务器）分：巨型机（“神威”、“天河”系列等）、小巨型机、大型机、小型机、工作站、个人计算机（PC）、嵌入式计算机（核心是 SoC 片上系统）。 （4）按主机外型：台式、便携式。 （5）按中央处理器的字长分：8 位、16 位、32 位、64 位等。 （6）计算机特性以及未来发展（微型化和智能化）： 目前的计算机使用的都是半导体集成电路，现在不断努力研究其他材料。 量子计算机：建立在量子力学基础上，可以同时使用多个不同的量子态来处理和存储信息。 光学计算机：以光子代替电子，光互连代替导线互连，光硬件代替计算机中的电子硬件，光运算代替电运算。 生物计算机：蛋白质分子与周围物理化学介质的相互作用过程。计算机的转换开关由酶来充当，而程序则在酶合成系统本身和蛋白质的结构中极其明显地表示出来。预计 10～20 年后，DNA 计算机将进入实用阶段。 5、计算机的特点：运算速度快、运算精度高、存储容量大、计算可靠性高（7×24 小时服务）、能进行逻辑判断、通用性好、支持人机交互等。 6、计算机的应用领域：科学计算（最早应用场景）、信息处理（办公自动化 OA）、计算机辅助技术（辅助设计 CAD；辅助制造 CAM、辅助教学 CAI、辅助测试 CAT）、过程控制、人工智能、网络应用、多媒体等。 7、一个完整计算机系统是由配套的硬件设备和软件系统组成。硬件主要由五大部件构成：运算器、控制器、存储器、输入设备和输出设备，它们通过总线相互连接。如下图所示： 主机：CPU、内存储器、总线等构成了计算机的“主机”。 外设（外部设备）：外部存储器（外存）和 I/O 设备构成。 CPU（中央处理器）：主要由运算器和控制器组成，也称微处理器。 8、按性能与用途划分的各类计算机：巨型计算机（超级计算机）采用并行处理，用于军事科研、气象预报、石油勘探、生物信息处理、飞机设计等领域，我国目前最快的是“神威·太湖之光”。大型计算机为企业、政府的海量数据提供集中的存储、管理和处理，承担主服务器（企业级服务器）的功能，可一二十年不间断运行。服务器是网络中专门为其他计算机提供资源和服务的计算机，需 7×24 小时运行，分为工作组级（家用）、部门级、企业级服务器，浪潮集团是我国最大的服务器制造商；服务器有三种应用方式：作为服务器、作为个人计算机、嵌入式应用。 9、计算机硬件组成：主机与外设：硬件是计算机系统中所有实际物理装置的总称，如 CPU 芯片、存储器芯片、鼠标、键盘、硬盘；硬件是软件的载体，软硬件缺一不可。CPU 和主存储器构成主机的主体部分，I/O 设备和辅助存储器构成外围设备（外设）。主存储器（内存、主存）存取速度快、容量小、成本高，断电后信息几乎消失（BIOS 中的只读 ROM 除外），属易失性存储器；它存放已经启动的应用程序和需立即处理的数据，CPU 处理的指令和数据直接从内存取得；主存与 CPU 高速连接，按字节编址（每个字节都有地址），是计算机的工作存储器。 10、计算机的诞生与发展：计算机速度不断提高、功能增加、体积缩小、成本降低、应用扩大，发展之快不断改写预测：早期 8～10 年运算速度提高十倍，而成本和体积降为原来的 1/10；20 世纪 80 年代开始，几乎每三年性能提高近四倍，成本下降一半。推动力是微电子技术的进展和计算机应用的需求。 11、操作系统的四大功能：操作系统的功能主要有四个： 处理器管理（宏观上同时执行、微观上单一执行，采用时间片轮转的处理策略） 存储管理（采用“虚拟存储技术”，虚拟存储器由物理内存和硬盘上的页面文件组成，使用 LRU 算法） 文件管理（多级层次式树状结构） 设备管理（通过“我的电脑”快捷菜单“属性”中的“设备管理器”进行）。 12、多任务处理的机制与前后台任务：多任务处理指多个任务在计算机中同时运行，每个任务都可以使用包括 CPU 在内的几乎全部软硬件资源。任务是指装入内存并启动执行的一个程序。为支持多任务处理，操作系统中的处理器调度程序负责把 CPU 时间分配给各个任务，使多个任务“同时”执行。调度程序采用按时间片轮转的方法，每个任务轮流得到一个时间片的 CPU 时间，时间片结束后再把 CPU 交给下一个任务，因此一个 CPU 就可以“同时”执行多个任务。 13、实用程序包括哪些：实用程序包括磁盘扫描程序、磁盘清理程序、磁盘碎片整理程序、备份程序、杀毒软件、基本输入输出系统（BIOS）、防火墙等。 14、1946 年美国宾夕法尼亚大学研制成功第 1 台电子数字计算机 ENIAC（十进制、未采用存储程序）；第一台按“存储程序控制”原理设计并采用二进制的计算机是 EDVAC（冯·诺依曼架构），第一台实际运行存储程序控制功能的计算机是 EDSAC。 15、计算机发展的四个阶段： 第四代大规模集成电路计算机时代（1971–至今）：大规模和超大规模集成电路，网络技术、多媒体技术等出现。 16、计算机系统是由硬件系统和软件系统组成。 硬件系统主要由五大部件构成：运算器、控制器、存储器、输入设备和输出设备，它们通过总线相互连接。 五大硬件部件以存储器为中心的连接结构与控制器工作流程如下图所示： 考向复习提示：计算机分类与存储程序原理 专转本常考主线：计算机四代划分以元器件为标志（电子管→晶体管→中小规模IC→大规模/超大规模IC）；冯·诺依曼“存储程序控制”核心思想在于程序与数据预先存入内存储器，由 CPU 自动连续取指并执行；计算机按性能划分为巨型机（超级计算机，我国神威系列）、大型机、小型机、微型机（PC）、嵌入式系统。 高频易错陷阱：冯·诺依曼架构五大逻辑部件 专转本常考单选：冯·诺依曼型计算机由五大基本逻辑部件组成：运算器、控制器、存储器、输入设备、输出设备；指令和数据均以二进制形式存放在同一个存储器中，由 CPU 顺序执行；常考陷阱选项故意将“存储器”偷换为“外存储器”或漏掉“控制器”，务必精准辨析。 考向复习提示：2025–2026 前沿同步：国产超算最新突破 应试提示：教材与历年真题常以 神威·太湖之光 作为我国超级计算机经典代表，作答传统考题时仍可沿用；以下为近年真实算力演进补充： • 超智融合演进：2023 年底发布的 天河星逸 系统部署于国家超算广州中心，显著强化通用计算与人工智能大模型融合算力； • 2026 年 6 月 TOP500 榜首回归：部署于国家超级计算深圳中心的我国自研超算 灵晟（LineShine） 以 2.198 Exaflop/s 性能登顶全球第一，采用全自主 `LingKun` 平台（`Armv9` 架构 304 核 `LX2` 处理器）与国产 `Kylin OS`。$kbpars$),(41, $kbpar$[{"t":"list","id":"a1-1-1-2-b1","imp":"normal","items":["1、CPU 即中央处理器，由运算器（ALU）、控制器（CU）和寄存器组（GPR）构成，用于执行系统软件和应用软件的处理器称为 CPU。CPU 是计算机必不可少的核心组成部件。","运算器用来对数据进行各种算术或逻辑运算，所以称为算术逻辑部件（ALU），参加 ALU 运算的操作数通常来自通用寄存器 GPR，运算结果也送回通用寄存器 GPR。","（1）运算器（ALU）：对数据进行算术运算、逻辑运算等。由算术逻辑单元（ALU）、累加器（ACC，中间结果）、程序状态字寄存器（PSW，存放是否溢出、运算结果是正是负等等）、通用寄存器组（可以编程指定通用寄存器组中的寄存器具有多种功能）等组成，它是数据加工处理部件。","（2）控制器（CU）：指挥计算机的各个部件按照指令的功能要求协调工作的部件。控制单元，取出指令并保存，解释指令的功能，由此产生控制各部件工作的信号，执行指令。控制器由程序计数器（指令计数器，简称 PC）、指令寄存器（IR）、指令译码器（ID）、时序产生器（时序电路）和操作控制器组成。"],"title":"","ordered":false},{"t":"img","id":"a1-1-1-2-b4","imp":"normal","src":"/kb-assets/pdf24/a1-cu-workflow.png","w":1680,"h":880,"alt":"CPU 控制单元与存储器、运算单元的数据交互框图","caption":"控制器工作循环：程序计数器 PC 提供指令地址，从内存取出指令送入指令寄存器 IR；控制器译码后向存储单元与运算单元发出控制信号","title":""},{"t":"list","id":"a1-1-1-2-b5","imp":"normal","items":["指令计数器（PC，程序计数器）：用来存放 CPU 正在执行的指令地址，CPU 按照该地址从内存读取所要执行的指令。","指令寄存器：用来保存当前正在执行（也有教材是说待执行或下一条）的指令，通过译码器解释该指令的含义，控制运算器的操作，记录 CPU 的内部状态等。","用户可见：通用寄存器组、程序状态字寄存器（PSW）、程序计数器（PC）。","用户不可见（透明）：存储器地址寄存器（MAR，主存中）、存储器数据寄存器（MDR，主存中）、指令寄存器等。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-2-b6","imp":"normal","items":["2、多核：使用双核（或多核）处理器的 PC 机中，是几个 CPU？集成在一块芯片上，物理上只有一个，逻辑上是两（或多）个。","3、CPU 的主要任务是执行指令，它按指令的规定对数据进行操作。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-2-b7","imp":"normal","items":["4、输入设备：把信息送入计算机的设备（以二进制形式）。常用的输入设备：键盘，鼠标、扫描仪、麦克风等。","5、输出设备：将计算机中的信息输出的设备（文字、图形、图像、声音等）。常用的输出设备：显示器、打印机、绘图仪、扬声器等。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-2-b8","imp":"normal","items":["6、PC 机组成：","（1）输入单元（input unit）：计算机的“接收”部分，从各种输入设备接收信息（数据和计算机程序），并将这些信息放到其他单元中，使信息得以处理。如今大多数信息通过键盘和鼠标输入计算机，将来也可能通过语音输入或扫描图形获得。","（2）输出单元（output unit）：计算机的“发送”部分，将计算机处理过的信息送到不同输出设备中，向计算机外部提供所需的信息。如今大多数信息通过屏幕显示、书面打印或用于控制其他设备输出。","（3）内存单元（memory unit）：计算机中快速访问、低容量的“库存”部分。","7、I/O 控制器与常见输入输出设备接口：I/O 控制器（input 和 output）负责输入输出控制。 常见输入设备：鼠标、键盘、扫描仪、数码相机、摄像头。 常见输出设备：显示器、打印机、绘图仪。 常用接口：串行口 COM（9 针）；并行口 LPT1（接打印机）；VGA 口（接显示器）；PS/2 口（接鼠标、键盘）；USB 高速通用串行接口，可接鼠标、键盘、外置光驱、U 盘、打印机等，有 1.1 和 2.0 两种类型，1.1 全速速率为 12Mb/s（约 1.5MB/s）。","（2）控制器（CU）：控制单元，取出指令并保存，解释指令的功能，由此产生控制各部件工作的信号，执行指令。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-1-2-b2","imp":"core","kind":"tip","text":"CPU 是计算机核心，由==运算器（ALU）、控制器、通用寄存器组（GPR）及内部总线==构成；其中==通用寄存器组是 CPU 内部存取速度最快==的存储单元；常用输入设备（键盘、鼠标、扫描仪）与输出设备（显示器、打印机、绘图仪）需熟练归类区分。","title":"考向复习提示：CPU 组成与常用 I/O 设备"},{"t":"callout","id":"a1-1-1-2-b3","imp":"core","kind":"trap","text":"专转本必考题：==程序计数器（PC）的作用是“存放 CPU 即将执行的下一条指令在内存中的地址”==，指令取出后 PC 自动加 1（指向紧随其后的下一条指令）；混淆选项常将 PC 功能说成“存放正在执行的指令”或“存放指令的操作数”，注意正在执行的指令存放于==指令寄存器（IR）==！","title":"高频易错陷阱：程序计数器 PC 的功能常考点"}]$kbpar$::jsonb, $kbpars$1、CPU 即中央处理器，由运算器（ALU）、控制器（CU）和寄存器组（GPR）构成，用于执行系统软件和应用软件的处理器称为 CPU。CPU 是计算机必不可少的核心组成部件。 运算器用来对数据进行各种算术或逻辑运算，所以称为算术逻辑部件（ALU），参加 ALU 运算的操作数通常来自通用寄存器 GPR，运算结果也送回通用寄存器 GPR。 （1）运算器（ALU）：对数据进行算术运算、逻辑运算等。由算术逻辑单元（ALU）、累加器（ACC，中间结果）、程序状态字寄存器（PSW，存放是否溢出、运算结果是正是负等等）、通用寄存器组（可以编程指定通用寄存器组中的寄存器具有多种功能）等组成，它是数据加工处理部件。 （2）控制器（CU）：指挥计算机的各个部件按照指令的功能要求协调工作的部件。控制单元，取出指令并保存，解释指令的功能，由此产生控制各部件工作的信号，执行指令。控制器由程序计数器（指令计数器，简称 PC）、指令寄存器（IR）、指令译码器（ID）、时序产生器（时序电路）和操作控制器组成。 指令计数器（PC，程序计数器）：用来存放 CPU 正在执行的指令地址，CPU 按照该地址从内存读取所要执行的指令。 指令寄存器：用来保存当前正在执行（也有教材是说待执行或下一条）的指令，通过译码器解释该指令的含义，控制运算器的操作，记录 CPU 的内部状态等。 用户可见：通用寄存器组、程序状态字寄存器（PSW）、程序计数器（PC）。 用户不可见（透明）：存储器地址寄存器（MAR，主存中）、存储器数据寄存器（MDR，主存中）、指令寄存器等。 2、多核：使用双核（或多核）处理器的 PC 机中，是几个 CPU？集成在一块芯片上，物理上只有一个，逻辑上是两（或多）个。 3、CPU 的主要任务是执行指令，它按指令的规定对数据进行操作。 4、输入设备：把信息送入计算机的设备（以二进制形式）。常用的输入设备：键盘，鼠标、扫描仪、麦克风等。 5、输出设备：将计算机中的信息输出的设备（文字、图形、图像、声音等）。常用的输出设备：显示器、打印机、绘图仪、扬声器等。 6、PC 机组成： （1）输入单元（input unit）：计算机的“接收”部分，从各种输入设备接收信息（数据和计算机程序），并将这些信息放到其他单元中，使信息得以处理。如今大多数信息通过键盘和鼠标输入计算机，将来也可能通过语音输入或扫描图形获得。 （2）输出单元（output unit）：计算机的“发送”部分，将计算机处理过的信息送到不同输出设备中，向计算机外部提供所需的信息。如今大多数信息通过屏幕显示、书面打印或用于控制其他设备输出。 （3）内存单元（memory unit）：计算机中快速访问、低容量的“库存”部分。 7、I/O 控制器与常见输入输出设备接口：I/O 控制器（input 和 output）负责输入输出控制。 常见输入设备：鼠标、键盘、扫描仪、数码相机、摄像头。 常见输出设备：显示器、打印机、绘图仪。 常用接口：串行口 COM（9 针）；并行口 LPT1（接打印机）；VGA 口（接显示器）；PS/2 口（接鼠标、键盘）；USB 高速通用串行接口，可接鼠标、键盘、外置光驱、U 盘、打印机等，有 1.1 和 2.0 两种类型，1.1 全速速率为 12Mb/s（约 1.5MB/s）。 （2）控制器（CU）：控制单元，取出指令并保存，解释指令的功能，由此产生控制各部件工作的信号，执行指令。 考向复习提示：CPU 组成与常用 I/O 设备 CPU 是计算机核心，由运算器（ALU）、控制器、通用寄存器组（GPR）及内部总线构成；其中通用寄存器组是 CPU 内部存取速度最快的存储单元；常用输入设备（键盘、鼠标、扫描仪）与输出设备（显示器、打印机、绘图仪）需熟练归类区分。 高频易错陷阱：程序计数器 PC 的功能常考点 专转本必考题：程序计数器（PC）的作用是“存放 CPU 即将执行的下一条指令在内存中的地址”，指令取出后 PC 自动加 1（指向紧随其后的下一条指令）；混淆选项常将 PC 功能说成“存放正在执行的指令”或“存放指令的操作数”，注意正在执行的指令存放于指令寄存器（IR）！$kbpars$),(42, $kbpar$[{"t":"list","id":"a1-1-1-3-b1","imp":"normal","items":["1、存储器是用于存储以二进位形式的程序和数据。分为内存储器（主存）和外存储器（辅存）。","2、内外存储器的区别：","（1）存取速度：内存要快，外存相对要慢。","（2）存储容量：内存要小（2G、4G、8G 等），外存要大（256G、512G、1T 等）。","（3）易失性：内存断电后消失，外存断电后保持。","（4）用途：内存存放启动运行的程序和需要立即处理的数据，外存长期存放计算机系统中所有信息。","（5）与 CPU 关系：CPU 从内存直接获得指令和数据进行处理（即 CPU 可以直接访问内存），外存的程序和数据需要载入内存之后才能被 CPU 使用。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-3-b4","imp":"normal","items":["3、总线用于连接 CPU、内存、外存和各种 I/O 设备并在它们之间传输信息的一组共享的传输线及其控制电路。","（1）CPU 总线（前端总线）：用于连接 CPU 和内存之间的总线。一般 CPU 总线的数据线条数为 CPU 位数。目前 CPU（Core i3/i5/i7/i9 都是 Intel）都是 64 位。CPU 总线速度决定着 CPU 与内存交换数据的速度。","（2）I/O 总线：用于连接主存和 I/O 设备（包括外设）总线（目前使用的 PCI 和 PCI-E）。","（3）按总线功能或信号类型分为：地址总线（传输地址信号）、数据总线（传输数据信号）、控制总线（传输控制信号）。","① 数据总线用于传送数据信息。数据总线是双向三态形式的总线，它既可以把 CPU 的数据传送到存储器或 I/O 接口等其他部件，也可以将其他部件的数据传送到 CPU。数据总线的位数是微型计算机的一个重要指标，通常与微处理器的字长相一致。","② 地址总线是专门用来传送地址的，由于地址只能从 CPU 传向存储器或 I/O 端口，所以地址总线总是单向三态的，这与数据总线不同。地址总线的位数决定了 CPU 可直接寻址的内存空间大小。地址总线位数与存储单元个数有关。例如，8 位微机的地址总线为 16 位，则其最大可寻址空间为 \\(2^{16} = 64\\) KB；16 位微机的地址总线为 20 位，则其可寻址空间为 \\(2^{20} = 1\\) MB。一般来说，若地址总线为 n 位，则可寻址空间为 \\(2^n\\) 字节。","③ 控制总线用来传送控制信号和时序信号。控制信号中，有的是微处理器送往存储器和 I/O 接口电路的，如读/写信号、片选信号、中断响应信号等；也有的是其他部件反馈给 CPU 的，如中断申请信号、复位信号、总线请求信号、设备就绪信号等。因此，控制总线的传送方向由具体控制信号而定，一般是双向的。控制总线的位数要根据系统的实际控制需要而定。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-3-b5","imp":"normal","items":["总线通常分为以下几类：","芯片内总线：用于集成电路芯片内部各部分的连接。CPU 总线是芯片内总线。","元件级总线：用于一块电路板内各元器件的连接。","内总线：又称系统总线，用于计算机各组成部分（CPU、内存和接口等）的连接。内总线有专用内总线和标准内总线之分，直接影响着整个计算机系统的性能。常见的内总线标准有 ISA 总线、EISA 总线和 PCI 总线等。系统总线分为：控制总线、数据总线、地址总线。","外总线：又称通信总线，用于计算机与外设或计算机与计算机之间的连接或通信。","外总线的标准有七八十种之多，RS-232C、USB 和 IEEE-1394 都是外总线标准。RS-232C 是一条串行外总线。通用串行总线 USB 是 1994 年底由 Compaq、IBM 和 Microsoft 等众多公司联合提出的，现在得到广泛应用。IEEE-1394 接口是由 Apple 和 TI 公司开发的高速外部串行总线标准，具有 800Mbps 的传输速度。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-3-b6","imp":"normal","items":["（4）总线带宽：","① 总线带宽指单位时间内总线上可以传输的最大的数据量。","② 总线带宽（MB/s）=（总线位宽/8）×总线工作频率（MHz）×每个总线周期数据传输的次数。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-3-b7","imp":"normal","items":["4、内存储器、外存储器与系统总线概述：","1）内存储器：计算机的内存储器是指 ROM 和 RAM，它是外存与 CPU 进行沟通的桥梁，计算机中所有程序的运行都在内存中进行。内存性能的强弱影响计算机整体发挥的水平。内存也称内存储器和主存储器，用于暂时存放 CPU 中的运算数据以及与硬盘等外部存储器交换的数据。","2）外存储器：指除计算机内存及 CPU 缓存以外的储存器，此类储存器一般断电后仍然能保存数据。","3）系统总线：总线是连接各个部件的信息传输线，是各个部件共享的传输介质。总线结构的计算机举例：单总线结构框图、面向 CPU 的双总线结构框图、以存储器为中心的双总线结构框图。","5、主存储器的功能与原理：主存是 CPU 可直接访问的存储器，用于存放供 CPU 处理的指令和数据。 特点：","以字节为单位进行连续编址，每个存储单元为 1 个字节（8 个二进位）。","存储容量：主存储器中所包含的存储单元的总数（单位 MB 或 GB）。","存取时间：从 CPU 送出内存单元的地址码开始，到主存读出数据并送到 CPU（或把 CPU 数据写入主存）所需要的时间，单位 ns，1 ns = \\(10^{-9}\\) s。","6、存储器的层状塔式结构：内存储器和外存储器组成一个层状的塔式结构。","1）目的：优化存储器的性能价格比。","2）存储器按读写速度由高到低排列：Cache、RAM、硬盘、光盘。","7、内存储器与外存储器的补充说明：外存不直接影响计算机的运行速度，影响计算机速度的主要是 CPU 和内存。内存由半导体芯片构成，可直接与 CPU 交换数据；外存由磁性介质、光学介质或闪存芯片构成，不能直接与 CPU 交换数据，需先调入内存。存储器的存取时间是指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间。","（1）CPU 总线（前端总线）：用于连接 CPU 和主存之间的总线。一般 CPU 总线的数据线条数为 CPU 位数。目前 CPU（i3/i5/i7/i9 等）都是 64 位。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-1-3-b2","imp":"core","kind":"tip","text":"存储系统按速度由高到低排列为：==寄存器 > 高速缓存 Cache > 内存储器（RAM/ROM） > 外存储器（SSD/机械硬盘/光盘）==；系统总线按传送信号划分为==数据总线（双向传送数据）、地址总线（单向传送物理地址，决定最大寻址空间）、控制总线（双向传送控制/时序信号）==。","title":"考向复习提示：存储层级塔式结构与系统总线分类"},{"t":"callout","id":"a1-1-1-3-b3","imp":"core","kind":"trap","text":"若 CPU 的地址总线为 32 位，则其最大可直接寻址空间为 ==\\(2^{32}\\) 字节 = 4 GB==；若地址总线为 36 位，最大寻址空间为 ==\\(2^{36}\\) 字节 = 64 GB==；常考陷阱是将寻址空间误算为“字”而非“字节”，计算机内存始终以==字节（8 位）==为基本编址单位！","title":"高频易错陷阱：地址总线宽度与寻址能力计算"}]$kbpar$::jsonb, $kbpars$1、存储器是用于存储以二进位形式的程序和数据。分为内存储器（主存）和外存储器（辅存）。 2、内外存储器的区别： （1）存取速度：内存要快，外存相对要慢。 （2）存储容量：内存要小（2G、4G、8G 等），外存要大（256G、512G、1T 等）。 （3）易失性：内存断电后消失，外存断电后保持。 （4）用途：内存存放启动运行的程序和需要立即处理的数据，外存长期存放计算机系统中所有信息。 （5）与 CPU 关系：CPU 从内存直接获得指令和数据进行处理（即 CPU 可以直接访问内存），外存的程序和数据需要载入内存之后才能被 CPU 使用。 3、总线用于连接 CPU、内存、外存和各种 I/O 设备并在它们之间传输信息的一组共享的传输线及其控制电路。 （1）CPU 总线（前端总线）：用于连接 CPU 和内存之间的总线。一般 CPU 总线的数据线条数为 CPU 位数。目前 CPU（Core i3/i5/i7/i9 都是 Intel）都是 64 位。CPU 总线速度决定着 CPU 与内存交换数据的速度。 （2）I/O 总线：用于连接主存和 I/O 设备（包括外设）总线（目前使用的 PCI 和 PCI-E）。 （3）按总线功能或信号类型分为：地址总线（传输地址信号）、数据总线（传输数据信号）、控制总线（传输控制信号）。 ① 数据总线用于传送数据信息。数据总线是双向三态形式的总线，它既可以把 CPU 的数据传送到存储器或 I/O 接口等其他部件，也可以将其他部件的数据传送到 CPU。数据总线的位数是微型计算机的一个重要指标，通常与微处理器的字长相一致。 ② 地址总线是专门用来传送地址的，由于地址只能从 CPU 传向存储器或 I/O 端口，所以地址总线总是单向三态的，这与数据总线不同。地址总线的位数决定了 CPU 可直接寻址的内存空间大小。地址总线位数与存储单元个数有关。例如，8 位微机的地址总线为 16 位，则其最大可寻址空间为 \(2^{16} = 64\) KB；16 位微机的地址总线为 20 位，则其可寻址空间为 \(2^{20} = 1\) MB。一般来说，若地址总线为 n 位，则可寻址空间为 \(2^n\) 字节。 ③ 控制总线用来传送控制信号和时序信号。控制信号中，有的是微处理器送往存储器和 I/O 接口电路的，如读/写信号、片选信号、中断响应信号等；也有的是其他部件反馈给 CPU 的，如中断申请信号、复位信号、总线请求信号、设备就绪信号等。因此，控制总线的传送方向由具体控制信号而定，一般是双向的。控制总线的位数要根据系统的实际控制需要而定。 总线通常分为以下几类： 芯片内总线：用于集成电路芯片内部各部分的连接。CPU 总线是芯片内总线。 元件级总线：用于一块电路板内各元器件的连接。 内总线：又称系统总线，用于计算机各组成部分（CPU、内存和接口等）的连接。内总线有专用内总线和标准内总线之分，直接影响着整个计算机系统的性能。常见的内总线标准有 ISA 总线、EISA 总线和 PCI 总线等。系统总线分为：控制总线、数据总线、地址总线。 外总线：又称通信总线，用于计算机与外设或计算机与计算机之间的连接或通信。 外总线的标准有七八十种之多，RS-232C、USB 和 IEEE-1394 都是外总线标准。RS-232C 是一条串行外总线。通用串行总线 USB 是 1994 年底由 Compaq、IBM 和 Microsoft 等众多公司联合提出的，现在得到广泛应用。IEEE-1394 接口是由 Apple 和 TI 公司开发的高速外部串行总线标准，具有 800Mbps 的传输速度。 （4）总线带宽： ① 总线带宽指单位时间内总线上可以传输的最大的数据量。 ② 总线带宽（MB/s）=（总线位宽/8）×总线工作频率（MHz）×每个总线周期数据传输的次数。 4、内存储器、外存储器与系统总线概述： 1）内存储器：计算机的内存储器是指 ROM 和 RAM，它是外存与 CPU 进行沟通的桥梁，计算机中所有程序的运行都在内存中进行。内存性能的强弱影响计算机整体发挥的水平。内存也称内存储器和主存储器，用于暂时存放 CPU 中的运算数据以及与硬盘等外部存储器交换的数据。 2）外存储器：指除计算机内存及 CPU 缓存以外的储存器，此类储存器一般断电后仍然能保存数据。 3）系统总线：总线是连接各个部件的信息传输线，是各个部件共享的传输介质。总线结构的计算机举例：单总线结构框图、面向 CPU 的双总线结构框图、以存储器为中心的双总线结构框图。 5、主存储器的功能与原理：主存是 CPU 可直接访问的存储器，用于存放供 CPU 处理的指令和数据。 特点： 以字节为单位进行连续编址，每个存储单元为 1 个字节（8 个二进位）。 存储容量：主存储器中所包含的存储单元的总数（单位 MB 或 GB）。 存取时间：从 CPU 送出内存单元的地址码开始，到主存读出数据并送到 CPU（或把 CPU 数据写入主存）所需要的时间，单位 ns，1 ns = \(10^{-9}\) s。 6、存储器的层状塔式结构：内存储器和外存储器组成一个层状的塔式结构。 1）目的：优化存储器的性能价格比。 2）存储器按读写速度由高到低排列：Cache、RAM、硬盘、光盘。 7、内存储器与外存储器的补充说明：外存不直接影响计算机的运行速度，影响计算机速度的主要是 CPU 和内存。内存由半导体芯片构成，可直接与 CPU 交换数据；外存由磁性介质、光学介质或闪存芯片构成，不能直接与 CPU 交换数据，需先调入内存。存储器的存取时间是指从 CPU 给出存储器地址开始，到存储器读出数据并送到 CPU（或把 CPU 的数据写入存储器）所需要的时间。 （1）CPU 总线（前端总线）：用于连接 CPU 和主存之间的总线。一般 CPU 总线的数据线条数为 CPU 位数。目前 CPU（i3/i5/i7/i9 等）都是 64 位。 考向复习提示：存储层级塔式结构与系统总线分类 存储系统按速度由高到低排列为：寄存器 > 高速缓存 Cache > 内存储器（RAM/ROM） > 外存储器（SSD/机械硬盘/光盘）；系统总线按传送信号划分为数据总线（双向传送数据）、地址总线（单向传送物理地址，决定最大寻址空间）、控制总线（双向传送控制/时序信号）。 高频易错陷阱：地址总线宽度与寻址能力计算 若 CPU 的地址总线为 32 位，则其最大可直接寻址空间为 \(2^{32}\) 字节 = 4 GB；若地址总线为 36 位，最大寻址空间为 \(2^{36}\) 字节 = 64 GB；常考陷阱是将寻址空间误算为“字”而非“字节”，计算机内存始终以字节（8 位）为基本编址单位！$kbpars$),(43, $kbpar$[{"t":"list","id":"a1-1-1-4-b1","imp":"normal","items":["1、程序（指令）和数据均以二进制编码表示，均存放在存储器中。","2、程序运行时候，CPU 从内存中一条一条取出指令和相应的数据，按指令操作码的规定，对数据进行运算处理，直到程序执行完毕为止。","3、指令是构成程序的基本单位，程序是由一连串指令组成。","4、指令的组成：操作码和操作数地址（地址码）。操作码不可少，操作码决定地址码是否有以及个数，操作数（地址码）可以没有。","操作码　操作数地址（地址码）","（1）操作码","① 操作码字段表征指令的操作特性与功能，如进行加法、取数等；操作码用来指明指令所要完成的操作，如加法、减法、取数、存数、移位等。","② 指令系统中的每一条指令都有一个唯一确定的操作码，指令不同，其操作码的编码也不同。","③ 为了能表示整个指令系统中的全部指令，指令的操作码字段应当具有足够的位数。一般来说，一个包含 n 位的操作码最多能表示 \\(2^n\\) 条指令。","（2）操作数地址（地址码）：指出该指令所操作（处理）的数据或者数据所在位置。地址码是用来指出该指令的源操作数的（一个或两个）、结果的地址以及下一条指令的地址。“地址”可以是主存的地址，也可以是寄存器的地址，甚至是 I/O 设备的地址。常见主存地址为例的地址码结构：四地址指令、三地址指令、二地址指令、一地址指令、零地址指令。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-4-b4","imp":"normal","items":["5、指令的执行过程：取指令、指令译码、执行指令、访存取数和结果写回。","（1）取指令：CPU 的控制器从存储器读取一条指令并放入指令寄存器。","（2）指令译码：指令寄存器中的指令经过译码，决定该指令应进行何种操作、操作数在哪里。","（3）执行指令：取出操作数并进行相应运算。","（4）保存：运算结果保存至寄存器，有时候也会保存至内存中。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-4-b5","imp":"normal","items":["6、指令系统：CPU 所能执行的全部指令称为该 CPU 的指令系统，即它的机器语言。","7、一般同一公司为解决软件兼容性问题，采用“向下兼容方式”开发新的处理器，即所有新处理器均保留老处理器的全部指令，同时还扩充功能更强的新指令。","8、智能手机和平板电脑使用的是 ARM 架构的 CPU，和 PC 上的 CPU 的指令系统不一样，所以不兼容。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-4-b6","imp":"normal","items":["9、计算机性能由许多因素（五大指标：字长、主频、内存容量、可靠性和可用性）决定，通常 CPU 是主要因素。影响 CPU 性能的主要因素：字长、指令系统、逻辑结构、高速缓存（Cache）、主频、内核数目等。","（1）字长（位数）：指通用寄存器和定点运算器的宽度（即二进制整数运算的位数）。字长都是字节的整数倍，以前都是 32 位的，目前 CPU（i3/i5/i7/i9）都是 64 位处理器。","（2）指令系统：指令的类型、数目和功能等都会影响程序的执行速度。","（3）逻辑结构（微架构）：CPU 包含的定点运算器和浮点运算器的数目、采用的流水线结构和级数、指令分支预测的机制、执行部件的数目、有无数字信号处理（DSP）功能等都对程序运行的速度有影响，甚至对某些特定应用有很大的影响。","（4）高速缓存（Cache）：高速缓存（Cache）的容量与结构（解决 CPU 与内存之间速度不匹配问题）。","（5）主频（CPU 内部时钟频率）：指 CPU 芯片中电子线路（门、触发器）的工作频率（时钟频率），它决定着 CPU 芯片内部数据传输与操作速度的快慢。主流高端 CPU 主频可以达到 3~4GHz，中低端可达到 2~3GHz。CPU 主频决定着 CPU 内部传输和操作速度的快慢。","（6）内核数：1 个、2 个、…、6 个、8 个甚至更多。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-4-b7","imp":"normal","items":["10、高速缓存（Cache）：","（1）Cache 一般由 SRAM（静态随机存储器）芯片组成，存取速度快于主存，小于 CPU。容量越大，级数越多，效果越好。Cache 缓解了 CPU 和内存之间速度不匹配的问题。不与主存统一编址。","（2）透明性：指 Cache 不能由程序或者程序员访问，不与主存统一编址。Cache 的地址空间和主存的地址空间是映射关系，Cache 和主存不统一编址，Cache 的地址空间也不是主存的一部分。Cache 是介于 CPU 处理器和主存储器之间的高速小容量存储器，因此它不属于主存的一部分。","（3）命中率：指的是 CPU 需要的指令或数据在 Cache 中直接找到的概率。","（4）Cache 中的数据是主存中部分内容的映像（副本），数据调入 Cache 由 CPU 自行完成，无须人为干预。","（5）Cache 技术是利用程序访问的局部性原理，把程序中正在使用的部分存放在一个高速的、容量较小的 Cache 中，使 CPU 的访存操作大多数针对 Cache 进行，从而大大提高程序的执行速度。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-4-b8","imp":"normal","items":["11、主频：指 CPU 芯片中电子线路（门、触发器）的工作频率（时钟频率），它决定着 CPU 芯片内部数据传输与操作速度的快慢。","（1）CPU 的工作频率（主频）= 外频（总线的工作频率、主存的工作频率）×倍频因子，外频一般为 100MHz、133MHz、266MHz。","（2）主频越高，CPU 的速度越快。","（3）单位一般是 Hz。常用 GHz。"],"title":"","ordered":false},{"t":"list","id":"a1-1-1-4-b9","imp":"normal","items":["12、处理器、微处理器与并行处理：处理器：能高速地进行算术运算和逻辑运算，负责对输入信息进行各种处理的部件。 微处理器：简称 μP 或 MP，通常指使用单片大规模集成电路制成的、具有运算和控制功能的处理器。 并行处理和多处理器系统：使用多个 CPU（中央处理器，2、4、8 个或更多）实现超高速计算的技术称为“并行处理”，采用这种技术的计算机系统称为“多处理器系统”。 这两个概念都是使用多个 CPU 的技术。 多核是指一个 CPU 芯片里有多个 CPU 内核。CPU 芯片强调的是物理上能看到的实体，CPU 强调的是逻辑上的功能模块。关于多核的最佳说法是：1 个 CPU 芯片里面有多个 CPU 内核。","13、计算机的性能指标：计算机的性能指标一般指的是：CPU 的性能、运算速度 MIPS、存储容量（主要指的是内存的容量）、存储周期等。","14、如何衡量 CPU 的性能：计算机的性能主要表现为程序执行速度的快慢。计算机性能由 CPU、内存、硬盘、显卡等多种因素决定，但 CPU 通常是主要因素。CPU 性能的高低主要表现为 CPU 的速度，常用的衡量方法有两种： 一是计算每秒钟可执行的指令数目，单位为 MIPS、MFLOPS。巨型计算机可达每秒千万亿至万万亿次基本运算，个人计算机为每秒几千万至几亿次基本运算。 二是 PC 大多以常用软件（办公软件、数字媒体处理软件和 3D 游戏等）的运行速度来测试 CPU 的性能，例如游戏性能测试程序 3DMark、整体综合性能测试程序 PCMark。","15、CPU 的兼容问题：不同公司生产的 CPU 各有自己的指令系统，它们未必互相兼容。Intel 公司的 CPU 与 AMD 公司的 CPU 相互兼容，但与 IBM 公司的 POWER 微处理器不兼容。","16、影响CPU 性能的主要因素：字长、指令系统、逻辑结构、高速缓存（Cache）、主频、内核数目等","（3）逻辑结构：CPU 包含的定点运算器和浮点运算器的数目、采用的流水线结构和级数、指令分支预测的机制、执行部件的数目等","（4）高速缓存（Cache）：高速缓存（cache）的容量与结构","（3）单位一般是Hz。","17、控制器与指令计数器：控制器是解释指令的含义、控制运算器的操作、记录内部状态的部件。指令计数器用来存放 CPU 正在执行的指令的地址，CPU 按照该地址从内存读取所要执行的指令。","18、指令的组成：操作码和操作数（地址码）。操作码不可少，地址码可以没有。","（1）操作码：指出CPU 应执行何种操作的一个命令词，例如加、减、乘、除等","（2）操作数（地址码）：指出该指令所操作(处理)的数据或者数据所在位置","19、指令的执行过程：取指令->指令译码->执行指令->保存"],"title":"","ordered":false},{"t":"callout","id":"a1-1-1-4-b2","imp":"core","kind":"tip","text":"微处理器核心指标包括：==主频（时钟频率）、字长（CPU 一次能同时处理的二进制位数，如 32 位/64 位）、核数与高速缓存容量==；一个指令周期包含==取指令、指令译码、执行指令与访存/写回==四个阶段。","title":"考向复习提示：微处理器主要性能指标与指令周期"},{"t":"callout","id":"a1-1-1-4-b3","imp":"core","kind":"trap","text":"==CISC（复杂指令集）==指令多且长短不一，多数指令可直接访存；而 ==RISC（精简指令集，如 ARM）==指令种类少、定长且格式简单，仅 Load/Store 指令可以访问内存，其余指令都在寄存器间执行，流水线效率高；考试极易颠倒两者特征。","title":"高频易错陷阱：RISC 与 CISC 架构的本质差异"},{"t":"callout","id":"a1-1-1-4-p2-sync-tip","imp":"core","kind":"tip","text":"在 `CISC`（`x86`）与 `RISC`（`ARM`）两大考纲主线之外，近年自主指令集与开源架构快速崛起：\n• ==RISC-V 开源第三极==：凭借开放免授权费特性，在工业控制、边缘 AI 与高性能芯片领域加速普及；我国中科院已推出开源高性能核香山与原生操作系统如意（适配最新 `RVA23` 标准），平头哥玄铁等服务器级 RISC-V 芯片已实现商用交付；\n• ==龙芯自主龙架构（LoongArch）==：桌面端 `3A6000` 与服务器端 ==`3C6000` 系列==（单硅片 16 核，经龙链高速互连可扩展至 64 核 128 线程）实现全栈自主可控；\n• ==华为鲲鹏与昇腾双底座==：通用算力侧 ==鲲鹏 950== 面向高核数通算替代，智能算力侧 ==昇腾（Ascend）== 通过自研 `HBM` 与超节点集群架构支撑超大规模 AI 训练与推理。","title":"考向复习提示：2025–2026 前沿同步：RISC-V 开源架构与国产处理器生态"}]$kbpar$::jsonb, $kbpars$1、程序（指令）和数据均以二进制编码表示，均存放在存储器中。 2、程序运行时候，CPU 从内存中一条一条取出指令和相应的数据，按指令操作码的规定，对数据进行运算处理，直到程序执行完毕为止。 3、指令是构成程序的基本单位，程序是由一连串指令组成。 4、指令的组成：操作码和操作数地址（地址码）。操作码不可少，操作码决定地址码是否有以及个数，操作数（地址码）可以没有。 操作码 操作数地址（地址码） （1）操作码 ① 操作码字段表征指令的操作特性与功能，如进行加法、取数等；操作码用来指明指令所要完成的操作，如加法、减法、取数、存数、移位等。 ② 指令系统中的每一条指令都有一个唯一确定的操作码，指令不同，其操作码的编码也不同。 ③ 为了能表示整个指令系统中的全部指令，指令的操作码字段应当具有足够的位数。一般来说，一个包含 n 位的操作码最多能表示 \(2^n\) 条指令。 （2）操作数地址（地址码）：指出该指令所操作（处理）的数据或者数据所在位置。地址码是用来指出该指令的源操作数的（一个或两个）、结果的地址以及下一条指令的地址。“地址”可以是主存的地址，也可以是寄存器的地址，甚至是 I/O 设备的地址。常见主存地址为例的地址码结构：四地址指令、三地址指令、二地址指令、一地址指令、零地址指令。 5、指令的执行过程：取指令、指令译码、执行指令、访存取数和结果写回。 （1）取指令：CPU 的控制器从存储器读取一条指令并放入指令寄存器。 （2）指令译码：指令寄存器中的指令经过译码，决定该指令应进行何种操作、操作数在哪里。 （3）执行指令：取出操作数并进行相应运算。 （4）保存：运算结果保存至寄存器，有时候也会保存至内存中。 6、指令系统：CPU 所能执行的全部指令称为该 CPU 的指令系统，即它的机器语言。 7、一般同一公司为解决软件兼容性问题，采用“向下兼容方式”开发新的处理器，即所有新处理器均保留老处理器的全部指令，同时还扩充功能更强的新指令。 8、智能手机和平板电脑使用的是 ARM 架构的 CPU，和 PC 上的 CPU 的指令系统不一样，所以不兼容。 9、计算机性能由许多因素（五大指标：字长、主频、内存容量、可靠性和可用性）决定，通常 CPU 是主要因素。影响 CPU 性能的主要因素：字长、指令系统、逻辑结构、高速缓存（Cache）、主频、内核数目等。 （1）字长（位数）：指通用寄存器和定点运算器的宽度（即二进制整数运算的位数）。字长都是字节的整数倍，以前都是 32 位的，目前 CPU（i3/i5/i7/i9）都是 64 位处理器。 （2）指令系统：指令的类型、数目和功能等都会影响程序的执行速度。 （3）逻辑结构（微架构）：CPU 包含的定点运算器和浮点运算器的数目、采用的流水线结构和级数、指令分支预测的机制、执行部件的数目、有无数字信号处理（DSP）功能等都对程序运行的速度有影响，甚至对某些特定应用有很大的影响。 （4）高速缓存（Cache）：高速缓存（Cache）的容量与结构（解决 CPU 与内存之间速度不匹配问题）。 （5）主频（CPU 内部时钟频率）：指 CPU 芯片中电子线路（门、触发器）的工作频率（时钟频率），它决定着 CPU 芯片内部数据传输与操作速度的快慢。主流高端 CPU 主频可以达到 3~4GHz，中低端可达到 2~3GHz。CPU 主频决定着 CPU 内部传输和操作速度的快慢。 （6）内核数：1 个、2 个、…、6 个、8 个甚至更多。 10、高速缓存（Cache）： （1）Cache 一般由 SRAM（静态随机存储器）芯片组成，存取速度快于主存，小于 CPU。容量越大，级数越多，效果越好。Cache 缓解了 CPU 和内存之间速度不匹配的问题。不与主存统一编址。 （2）透明性：指 Cache 不能由程序或者程序员访问，不与主存统一编址。Cache 的地址空间和主存的地址空间是映射关系，Cache 和主存不统一编址，Cache 的地址空间也不是主存的一部分。Cache 是介于 CPU 处理器和主存储器之间的高速小容量存储器，因此它不属于主存的一部分。 （3）命中率：指的是 CPU 需要的指令或数据在 Cache 中直接找到的概率。 （4）Cache 中的数据是主存中部分内容的映像（副本），数据调入 Cache 由 CPU 自行完成，无须人为干预。 （5）Cache 技术是利用程序访问的局部性原理，把程序中正在使用的部分存放在一个高速的、容量较小的 Cache 中，使 CPU 的访存操作大多数针对 Cache 进行，从而大大提高程序的执行速度。 11、主频：指 CPU 芯片中电子线路（门、触发器）的工作频率（时钟频率），它决定着 CPU 芯片内部数据传输与操作速度的快慢。 （1）CPU 的工作频率（主频）= 外频（总线的工作频率、主存的工作频率）×倍频因子，外频一般为 100MHz、133MHz、266MHz。 （2）主频越高，CPU 的速度越快。 （3）单位一般是 Hz。常用 GHz。 12、处理器、微处理器与并行处理：处理器：能高速地进行算术运算和逻辑运算，负责对输入信息进行各种处理的部件。 微处理器：简称 μP 或 MP，通常指使用单片大规模集成电路制成的、具有运算和控制功能的处理器。 并行处理和多处理器系统：使用多个 CPU（中央处理器，2、4、8 个或更多）实现超高速计算的技术称为“并行处理”，采用这种技术的计算机系统称为“多处理器系统”。 这两个概念都是使用多个 CPU 的技术。 多核是指一个 CPU 芯片里有多个 CPU 内核。CPU 芯片强调的是物理上能看到的实体，CPU 强调的是逻辑上的功能模块。关于多核的最佳说法是：1 个 CPU 芯片里面有多个 CPU 内核。 13、计算机的性能指标：计算机的性能指标一般指的是：CPU 的性能、运算速度 MIPS、存储容量（主要指的是内存的容量）、存储周期等。 14、如何衡量 CPU 的性能：计算机的性能主要表现为程序执行速度的快慢。计算机性能由 CPU、内存、硬盘、显卡等多种因素决定，但 CPU 通常是主要因素。CPU 性能的高低主要表现为 CPU 的速度，常用的衡量方法有两种： 一是计算每秒钟可执行的指令数目，单位为 MIPS、MFLOPS。巨型计算机可达每秒千万亿至万万亿次基本运算，个人计算机为每秒几千万至几亿次基本运算。 二是 PC 大多以常用软件（办公软件、数字媒体处理软件和 3D 游戏等）的运行速度来测试 CPU 的性能，例如游戏性能测试程序 3DMark、整体综合性能测试程序 PCMark。 15、CPU 的兼容问题：不同公司生产的 CPU 各有自己的指令系统，它们未必互相兼容。Intel 公司的 CPU 与 AMD 公司的 CPU 相互兼容，但与 IBM 公司的 POWER 微处理器不兼容。 16、影响CPU 性能的主要因素：字长、指令系统、逻辑结构、高速缓存（Cache）、主频、内核数目等 （3）逻辑结构：CPU 包含的定点运算器和浮点运算器的数目、采用的流水线结构和级数、指令分支预测的机制、执行部件的数目等 （4）高速缓存（Cache）：高速缓存（cache）的容量与结构 （3）单位一般是Hz。 17、控制器与指令计数器：控制器是解释指令的含义、控制运算器的操作、记录内部状态的部件。指令计数器用来存放 CPU 正在执行的指令的地址，CPU 按照该地址从内存读取所要执行的指令。 18、指令的组成：操作码和操作数（地址码）。操作码不可少，地址码可以没有。 （1）操作码：指出CPU 应执行何种操作的一个命令词，例如加、减、乘、除等 （2）操作数（地址码）：指出该指令所操作(处理)的数据或者数据所在位置 19、指令的执行过程：取指令->指令译码->执行指令->保存 考向复习提示：微处理器主要性能指标与指令周期 微处理器核心指标包括：主频（时钟频率）、字长（CPU 一次能同时处理的二进制位数，如 32 位/64 位）、核数与高速缓存容量；一个指令周期包含取指令、指令译码、执行指令与访存/写回四个阶段。 高频易错陷阱：RISC 与 CISC 架构的本质差异 CISC（复杂指令集）指令多且长短不一，多数指令可直接访存；而 RISC（精简指令集，如 ARM）指令种类少、定长且格式简单，仅 Load/Store 指令可以访问内存，其余指令都在寄存器间执行，流水线效率高；考试极易颠倒两者特征。 考向复习提示：2025–2026 前沿同步：RISC-V 开源架构与国产处理器生态 在 `CISC`（`x86`）与 `RISC`（`ARM`）两大考纲主线之外，近年自主指令集与开源架构快速崛起： • RISC-V 开源第三极：凭借开放免授权费特性，在工业控制、边缘 AI 与高性能芯片领域加速普及；我国中科院已推出开源高性能核香山与原生操作系统如意（适配最新 `RVA23` 标准），平头哥玄铁等服务器级 RISC-V 芯片已实现商用交付； • 龙芯自主龙架构（LoongArch）：桌面端 `3A6000` 与服务器端 `3C6000` 系列（单硅片 16 核，经龙链高速互连可扩展至 64 核 128 线程）实现全栈自主可控； • 华为鲲鹏与昇腾双底座：通用算力侧 鲲鹏 950 面向高核数通算替代，智能算力侧 昇腾（Ascend） 通过自研 `HBM` 与超节点集群架构支撑超大规模 AI 训练与推理。$kbpars$);
do $$
declare r record; o record; v integer;
begin
  for r in select node_id, blocks, search_text from _kbpar order by node_id loop
    select rev_no, html, source_ref into o from kb_revision
     where node_id = r.node_id and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 无已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v, r.blocks, o.html, r.search_text, o.source_ref);
    update kb_entry set published_rev = v, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
